"use client";

import React, { useEffect, useState } from "react";

const LOGO_URL = "data:image/png;base64,";

const mapel = [
  { nama: "Matematika", kelompok: "Umum", jam: 4 },
  { nama: "Bahasa Inggris", kelompok: "Umum", jam: 3 },
  { nama: "Basis Data", kelompok: "Kejuruan", jam: 6 },
  { nama: "Basis Data Lanjutan", kelompok: "Kejuruan", jam: 4 },
  { nama: "Pemrograman Web", kelompok: "Kejuruan", jam: 6 },
  { nama: "Jaringan Komputer", kelompok: "Kejuruan", jam: 6 },
];
const jadwal = [
  { kelas: "XI TKJ 2", hari: "Senin", jam: "07.00 - 08.30", mapel: "Jaringan Komputer" },
  { kelas: "XII PPLG 2", hari: "Selasa", jam: "08.30 - 10.00", mapel: "Basis Data" },
  { kelas: "X DKV 1", hari: "Rabu", jam: "10.15 - 11.45", mapel: "Bahasa Inggris" },
];
const penugasan = [
  { guru: "Ahmad Fauzan", mapel: "Basis Data", kelas: "XII PPLG 2" },
  { guru: "Dewi Lestari, S.Pd.", mapel: "Bahasa Inggris", kelas: "X DKV 1" },
  { guru: "Rina Amelia", mapel: "Pemrograman Web", kelas: "XI PPLG 1" },
  { guru: "Budi Santoso", mapel: "Matematika", kelas: "X RPL 2" },
];
const log = [
  ['Mapel "Basis Data Lanjutan" berhasil ditambahkan ke kurikulum', "hari ini"],
  ["Penugasan baru: Dewi Lestari, S.Pd. mengajar Bahasa Inggris di X DKV 1", "kemarin"],
  ["Jadwal kelas XI TKJ 2 diperbarui", "2 hari yang lalu"],
];

const IC = {
  grid: '<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  book: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z"/>',
  cal: '<rect x="3" y="4" width="18" height="18" rx="2"/><path d="M16 2v4M8 2v4M3 10h18"/>',
  users: '<circle cx="9" cy="8" r="4"/><path d="M2 21c0-4 3-7 7-7s7 3 7 7"/><path d="M17 4a4 4 0 0 1 0 8M22 21c0-3-2-5-4-6"/>',
  act: '<polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/>',
  doc: '<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8Z"/><path d="M14 2v6h6M9 13h6M9 17h6"/>',
  user: '<circle cx="12" cy="8" r="4"/><path d="M4 21c0-4 4-7 8-7s8 3 8 7"/>',
};

const PAGES = [
  ["home", "Beranda", "grid"],
  ["mapel", "Mata Pelajaran", "book"],
  ["jadwal", "Jadwal Pelajaran", "cal"],
  ["penugasan", "Penugasan Guru", "users"],
  ["aktivitas", "Aktivitas Pembelajaran", "act"],
  ["laporan", "Laporan", "doc"],
  ["profil", "Profil", "user"],
];

const uniq = (a) => new Set(a).size;
const guruDari = (nama) => penugasan.filter((p) => p.mapel === nama).map((p) => p.guru);

function Icon({ name }) {
  return (
    <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" dangerouslySetInnerHTML={{ __html: IC[name] }} />
  );
}

function DataTable({ title, sub, cols, rows }) {
  return (
    <>
      <h2>{title}</h2>
      <p className="sub">{sub}</p>
      <section className="card wrap">
        <table>
          <tbody>
            <tr>{cols.map(([, l]) => <th key={l}>{l}</th>)}</tr>
            {rows.map((r, i) => (
              <tr key={i}>{cols.map(([k]) => <td key={k}>{r[k]}</td>)}</tr>
            ))}
          </tbody>
        </table>
      </section>
    </>
  );
}

export default function DashboardKurikulum() {
  const [loggedIn, setLoggedIn] = useState(true);
  const [page, setPage] = useState("home");
  const [toastMsg, setToastMsg] = useState("");

  useEffect(() => {
    document.documentElement.setAttribute("data-theme", "light");
  }, []);

  const toast = (t) => {
    setToastMsg(t);
    setTimeout(() => setToastMsg(""), 2200);
  };
  const goto = (p) => {
    setPage(p);
    window.scrollTo(0, 0);
  };

  const unduhCsv = () => {
    const rows = [["Mata Pelajaran", "Kelompok", "Guru Pengampu", "Jam/Minggu"], ...mapel.map((m) => [m.nama, m.kelompok, guruDari(m.nama).join("; "), m.jam])];
    const csv = rows.map((r) => r.map((c) => '"' + String(c).replace(/"/g, '""') + '"').join(",")).join("\n");
    const a = document.createElement("a");
    a.href = URL.createObjectURL(new Blob([csv], { type: "text/csv" }));
    a.download = "laporan-kurikulum.csv";
    a.click();
    toast("Laporan diunduh");
  };

  if (!loggedIn) {
    return (
      <>
        <style>{CSS}</style>
        <div className="login">
          <div className="lbox">
            <div className="ltop">
              <img src={LOGO_URL} alt="Logo" />
              <svg viewBox="0 0 90 74" width="86" height="70">
                <rect x="30" y="8" width="52" height="38" rx="4" fill="#eaf0f5" stroke="#3B5B7A" strokeWidth="2" />
                <rect x="35" y="13" width="42" height="24" rx="2" fill="#fff" />
                <path d="M40 18h20M40 23h32M40 28h26" stroke="#c9a227" strokeWidth="2" strokeLinecap="round" />
                <rect x="42" y="51" width="28" height="4" rx="2" fill="#3B5B7A" />
                <circle cx="18" cy="24" r="15" fill="#fff" stroke="#c9a227" strokeWidth="2" />
                <path d="M9 20h18M9 24h18M9 28h12" stroke="#3B5B7A" strokeWidth="2" strokeLinecap="round" />
                <circle cx="20" cy="56" r="9" fill="none" stroke="#3B5B7A" strokeWidth="2.5" />
                <line x1="27" y1="63" x2="34" y2="70" stroke="#3B5B7A" strokeWidth="3" strokeLinecap="round" />
              </svg>
            </div>
            <h1>Selamat Datang!</h1>
            <p>Login untuk melanjutkan ke sistem</p>
            <label className="llabel">Username</label>
            <div className="lfield"><span>👤</span><input value="waka.kurikulum" disabled readOnly /></div>
            <label className="llabel">Password</label>
            <div className="lfield"><span>🔒</span><input type="password" value="12345678" disabled readOnly /><span>👁️</span></div>
            <div className="lact">
              <button className="btn p" onClick={() => setLoggedIn(true)}>Login</button>
              <button className="btn p" style={{ opacity: 0.85 }} onClick={() => toast("Hubungi admin untuk reset password")}>Lupa Password</button>
            </div>
            <div className="lfoot">
              <b>LMS SMK Citra Negara</b>
              <p style={{ margin: "2px 0 0" }}>Platform Pembelajaran Digital</p>
            </div>
          </div>
        </div>
        {toastMsg && <div id="toast">{toastMsg}</div>}
      </>
    );
  }

  return (
    <>
      <style>{CSS}</style>
      <div id="app">
        <aside>
          <div className="brand">
            <div className="logo"><img src={LOGO_URL} alt="Logo" /></div>
            <div><b>LMS</b><small>SMK CITRA NEGARA</small></div>
          </div>
          <nav>
            {PAGES.map(([k, l, ic]) => (
              <button key={k} className={"nav-item" + (page === k ? " on" : "")} onClick={() => goto(k)}>
                <Icon name={ic} />
                {l}
              </button>
            ))}
          </nav>
          <div className="bot">
            <button onClick={() => setLoggedIn(false)}>
              <svg viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
                <polyline points="16 17 21 12 16 7" />
                <line x1="21" y1="12" x2="9" y2="12" />
              </svg>
              Keluar
            </button>
          </div>
        </aside>

        <main>
          <div className="top">
            <span>LMS SMK CITRA NEGARA</span>
            <div className="me"><b>Waka Kurikulum</b><div className="av">WK</div></div>
          </div>

          <div id="view">
            {page === "home" && (
              <>
                <h2>Selamat datang, Waka Kurikulum</h2>
                <p className="sub">Ringkasan struktur kurikulum sekolah</p>
                <div className="stats">
                  <div className="stat"><small>Total mata pelajaran</small><b>{mapel.length}</b></div>
                  <div className="stat"><small>Guru aktif</small><b>{uniq(penugasan.map((p) => p.guru))}</b></div>
                  <div className="stat"><small>Jumlah kelas</small><b>{uniq([...jadwal.map((j) => j.kelas), ...penugasan.map((p) => p.kelas)])}</b></div>
                  <div className="stat"><small>Jadwal aktif</small><b style={{ fontSize: 22 }}>Semester ganjil</b><em>Tahun 2026/2027</em></div>
                </div>
                <section className="card">
                  <h3>Aktivitas terbaru</h3>
                  {log.map((l, i) => (
                    <div className="row" key={i}><b>{l[0]}</b><div className="mu">{l[1]}</div></div>
                  ))}
                </section>
              </>
            )}

            {page === "mapel" && (
              <DataTable title="Mata Pelajaran" sub="Daftar mata pelajaran kurikulum." cols={[["nama", "Nama Mapel"], ["kelompok", "Kelompok"], ["jam", "Jam/Minggu"]]} rows={mapel} />
            )}
            {page === "jadwal" && (
              <DataTable title="Jadwal Pelajaran" sub="Jadwal pelajaran tiap kelas." cols={[["kelas", "Kelas"], ["hari", "Hari"], ["jam", "Jam"], ["mapel", "Mata Pelajaran"]]} rows={jadwal} />
            )}
            {page === "penugasan" && (
              <DataTable title="Penugasan Guru" sub="Guru pengampu mapel di tiap kelas." cols={[["guru", "Guru"], ["mapel", "Mata Pelajaran"], ["kelas", "Kelas"]]} rows={penugasan} />
            )}

            {page === "aktivitas" && (
              <>
                <h2>Aktivitas Pembelajaran</h2>
                <p className="sub">Riwayat aktivitas kurikulum, jadwal, dan penugasan.</p>
                <section className="card">
                  {log.map((l, i) => (
                    <div className="row" key={i}><b>{l[0]}</b><div className="mu">{l[1]}</div></div>
                  ))}
                </section>
              </>
            )}

            {page === "laporan" && (
              <>
                <div className="toolbar">
                  <div>
                    <h2>Laporan</h2>
                    <p className="sub" style={{ margin: 0 }}>Rekap mapel, guru pengampu, dan jam pelajaran.</p>
                  </div>
                  <button className="btn p" onClick={unduhCsv}>Unduh CSV</button>
                </div>
                <section className="card wrap">
                  <table>
                    <tbody>
                      <tr><th>Mata Pelajaran</th><th>Kelompok</th><th>Guru Pengampu</th><th>Jam/Minggu</th></tr>
                      {mapel.map((m) => (
                        <tr key={m.nama}>
                          <td>{m.nama}</td>
                          <td>{m.kelompok}</td>
                          <td>{guruDari(m.nama).join(", ") || "-"}</td>
                          <td>{m.jam}</td>
                        </tr>
                      ))}
                    </tbody>
                  </table>
                </section>
              </>
            )}

            {page === "profil" && (
              <>
                <h2>Profil</h2>
                <p className="sub">Data akun Waka Kurikulum.</p>
                <section className="card">
                  <div className="row" style={{ display: "flex", gap: 14, alignItems: "center" }}>
                    <div className="av" style={{ width: 56, height: 56, fontSize: 18 }}>WK</div>
                    <div><b style={{ fontSize: 16 }}>Waka Kurikulum</b><div className="mu">SMK Citra Negara</div></div>
                  </div>
                  {[
                    ["Jabatan", "Wakil Kepala Sekolah Bidang Kurikulum"],
                    ["Tahun Ajaran", "2026/2027"],
                    ["Email", "kurikulum@smkcitranegara.sch.id"],
                  ].map((r) => (
                    <div className="row" key={r[0]} style={{ display: "flex", justifyContent: "space-between" }}>
                      <span className="mu">{r[0]}</span>
                      <span>{r[1]}</span>
                    </div>
                  ))}
                </section>
              </>
            )}
          </div>
        </main>
      </div>
      {toastMsg && <div id="toast">{toastMsg}</div>}
    </>
  );
}

const CSS = `:root{--brand:#3B5B7A;--dark:#2C4661;--gold:#c9a227;--bg:#f1f4f7;--card:#fff;--tx:#1f2933;--mu:#64748b;--ln:#e2e8f0;--ok:#e7f6ec;--okt:#1a7f37;--bad:#fdecea;--badt:#b42318;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
html{scroll-padding-top:env(safe-area-inset-top,0px)}
*{box-sizing:border-box}[hidden]{display:none!important}
body{margin:0;background:var(--bg);color:var(--tx);font:14px/1.5 system-ui,-apple-system,"Segoe UI",Roboto,sans-serif}
#app{display:flex;min-height:100vh}
aside{width:232px;background:var(--brand);color:#fff;display:flex;flex-direction:column;position:sticky;top:0;height:100vh;flex-shrink:0}
.brand{display:flex;gap:10px;align-items:center;padding:18px;border-bottom:1px solid #ffffff22}
.logo{width:40px;height:40px;border-radius:50%;background:#fff;display:grid;place-items:center;flex-shrink:0;padding:4px}
.logo img{width:100%;height:100%;object-fit:contain}
.brand b{font-size:13px;display:block;line-height:1.2}.brand small{font-size:11px;opacity:.7}
nav{flex:1;padding:14px;display:flex;flex-direction:column;gap:6px;overflow-y:auto}
.nav-item{background:none;color:#ffffffe6;text-align:left;padding:10px 16px;border-radius:999px;cursor:pointer;font:inherit;border:0;display:flex;align-items:center;gap:10px;font-weight:500}
.nav-item:hover{background:#ffffff1a}.nav-item.on{background:#fff;color:var(--brand);font-weight:600}
.bot{padding:14px;border-top:1px solid #ffffff22}
.bot button{color:#fca5a5;width:100%;background:none;border:0;cursor:pointer;font:inherit;display:flex;align-items:center;gap:8px;padding:9px 14px}
main{flex:1;min-width:0}
.top{display:flex;justify-content:space-between;align-items:center;padding:12px 24px;background:var(--card);border-bottom:1px solid var(--ln)}
.top span{color:var(--brand);font-weight:600;font-size:12px;letter-spacing:.03em}
.me{display:flex;gap:10px;align-items:center;text-align:right;line-height:1.2}
.av{width:34px;height:34px;border-radius:50%;background:var(--gold);color:#fff;display:grid;place-items:center;font-weight:700;font-size:12px}
#view{padding:24px;max-width:1100px}
h2{margin:0 0 4px;font-size:18px}.sub{color:var(--mu);margin:0 0 16px;font-size:13px}
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}
.stat{background:var(--card);border:1px solid var(--ln);border-radius:14px;padding:16px}
.stat small{color:var(--mu);font-size:12px}.stat b{display:block;font-size:26px;margin-top:4px}.stat em{font-style:normal;color:var(--brand);font-size:12px}
.card{background:var(--card);border:1px solid var(--ln);border-radius:14px;margin-bottom:16px;overflow:hidden}
.card>h3{margin:0;padding:14px 18px;font-size:15px;border-bottom:1px solid var(--ln)}
.row{padding:12px 18px;border-bottom:1px solid var(--ln)}.row:last-child{border:0}
.mu{color:var(--mu);font-size:12px}
table{width:100%;border-collapse:collapse}th,td{padding:10px 18px;text-align:left;border-bottom:1px solid var(--ln)}
th{color:var(--mu);font-weight:500;font-size:12px}tr:last-child td{border:0}
.btn{border:1px solid var(--ln);background:var(--card);color:var(--tx);border-radius:8px;padding:7px 14px;cursor:pointer;font:inherit;font-size:13px}
.btn:hover{border-color:var(--brand)}.btn.p{background:var(--brand);border-color:var(--brand);color:#fff}
.btn.e{color:var(--brand);border-color:var(--brand)}.btn.d{color:var(--badt);border-color:#f3b9b4}
.acts{display:flex;gap:8px;justify-content:flex-end}
.toolbar{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:14px;gap:10px;flex-wrap:wrap}
.wrap{overflow-x:auto}
.modal{position:fixed;inset:0;background:#0009;display:grid;place-items:center;padding:16px;z-index:9}
.box{background:var(--card);border-radius:14px;padding:20px;width:100%;max-width:420px;max-height:85vh;overflow:auto}.box h3{margin:0 0 14px}
.field{display:block;margin-bottom:12px}.field span{display:block;font-size:12px;color:var(--mu);margin-bottom:4px;font-weight:500}
.field input,.field select{width:100%;padding:9px 12px;border:1px solid var(--ln);border-radius:8px;font:inherit;background:var(--bg);color:var(--tx)}
.login{position:fixed;inset:0;background:linear-gradient(180deg,#243b52,#3B5B7A);display:grid;place-items:center;z-index:20;padding:16px;overflow:auto}
.lbox{background:#fff;border-radius:22px;padding:30px 28px;width:100%;max-width:360px;text-align:center;box-shadow:0 20px 50px #0f172a59}
.ltop{display:flex;align-items:center;justify-content:center;gap:14px}.ltop img{width:70px;height:70px;object-fit:contain}
.lbox h1{font-size:19px;margin:8px 0 2px}.lbox p{color:var(--mu);font-size:12.5px;margin:0 0 14px}
.llabel{display:block;text-align:left;font-size:11px;font-weight:600;letter-spacing:.04em;color:var(--mu);text-transform:uppercase;margin:12px 0 6px}
.lfield{display:flex;gap:8px;background:var(--bg);border:1px solid var(--ln);border-radius:10px;padding:10px 12px}
.lfield input{flex:1;border:0;background:none;font:inherit;outline:none}
.lact{display:flex;gap:10px;margin-top:18px}.lact .btn{flex:1;padding:10px 0}
.lfoot{margin-top:20px;padding-top:14px;border-top:1px solid var(--ln)}.lfoot b{color:var(--brand);font-size:14px}
#toast{position:fixed;bottom:calc(20px + env(safe-area-inset-bottom,0px));left:50%;transform:translateX(-50%);background:var(--dark);color:#fff;padding:9px 16px;border-radius:99px;font-size:13px;z-index:30}
@media(max-width:760px){#app{flex-direction:column}aside{width:100%;height:auto;position:static}nav{flex-direction:row;overflow-x:auto}.nav-item{white-space:nowrap}.stats{grid-template-columns:1fr 1fr}#view{padding:16px}.top{padding:10px 16px}}`;